return-response.set-body:
@{

                    return JsonConvert.SerializeObject(new {
                        status = context.Response.StatusCode,
                        error = context.LastError.Reason,
                        error_message = context.LastError.Message,
                        api_name = context.Api.Name,
                        scope = context.LastError.Scope,
                        section = context.LastError.Section,
                        resource = context.Request.OriginalUrl.ToString(),
                        timezone_ist = TimeZoneInfo.ConvertTimeBySystemTimeZoneId(DateTime.UtcNow, "India Standard Time").ToString("dd-MM-yyyy HH:mm:ss"),
                        correlation = context.Request.Headers.GetValueOrDefault("x-correlation-id", context.RequestId.ToString())
                    });

                }
